test("Final Validation submission is explicit and scheduler completion remains unvalidated", async ({ page }) => {
  const finalCampaign = {
    ...campaign,
    stage: "final_validation",
    progress: [{ stage: "final_validation", completed: 0, expected: 120, status: "not-started" }],
  };
  const receipt = "d".repeat(64);
  const empty = {
    dependency: "afterok within each family",
    families: [
      { id: "angled_donut", array_job_id: null, merge_job_id: null },
      { id: "single_pass", array_job_id: null, merge_job_id: null },
    ],
  };
  const submitted = {
    dependency: "afterok within each family",
    families: [
      { id: "angled_donut", array_job_id: "910[].zeus-master", merge_job_id: "911.zeus-master" },
      { id: "single_pass", array_job_id: "912[].zeus-master", merge_job_id: "913.zeus-master" },
    ],
  };
  let confirmed = false;
  await page.route("**/api/v1/campaigns", (route) => route.fulfill({ json: { api_version: 1, data: { campaigns: [finalCampaign], invalid_count: 0, total: 1 } } }));
  await page.route(`**/api/v1/campaigns/${id}`, (route) => route.fulfill({ json: { api_version: 1, data: finalCampaign } }));
  await page.route("**/api/v1/session", (route) => route.fulfill({ json: { api_version: 1, data: { csrf_token: "csrf" } } }));
  await page.route("**/api/v1/zeus/snapshot", (route) => route.fulfill({ json: { api_version: 1, data: { connection_status: "connected", profile, remote: { project_directory: profile.project_directory, git_commit: "a".repeat(40), branch: "main", dirty: false }, scheduler: { status: "available", queried_at: "2026-10-12T10:00:00Z", jobs: [] } } } }));
  await page.route("**/api/v1/zeus/submissions/mot-3d-final-validation/status", (route) => route.fulfill({ json: { api_version: 1, data: { source: "zeus", queried_at: "2026-10-12T10:00:00Z", campaign: { id, name: campaign.name, stage: "final_validation" }, submission: { status: confirmed ? "completed_success_unvalidated" : "not_submitted", chain: confirmed ? submitted : empty }, scheduler: { expected_array_tasks: 6, expected_merge_jobs: 2, completed_array_tasks: confirmed ? 6 : 0, completed_merge_jobs: confirmed ? 2 : 0 }, validation: { status: "not_started", expected_candidates_per_family: 1, expected_recoil_seeds_per_candidate: 3 }, next_action: confirmed ? "await_result_synchronization" : "review_submission", local_sync: { status: "synchronized", receipt_sha256: receipt } } } }));
  await page.route("**/api/v1/zeus/submissions/mot-3d-final-validation/preview", (route) => route.fulfill({ json: { api_version: 1, data: { preview_token: "final-validation-token", expires_in_seconds: 300, campaign: { id, name: campaign.name, git_commit: "a".repeat(40) }, stage: { id: "final_validation", label: "Final Validation" }, chain: { families: [{ id: "angled_donut", array_tasks: 3, merge_jobs: 1 }, { id: "single_pass", array_tasks: 3, merge_jobs: 1 }], qsub_calls: 4, dependency: "afterok within each family" }, resources: { array: { ncpus_per_task: 200, memory_gb_per_task: 64, walltime: "24:00:00" }, merge: { ncpus: 1, memory_gb: 8, walltime: "02:00:00" } }, science: { classification: "sealed_unbiased_final_validation", candidates_per_family: 1, input_ensembles: 20, recoil_seeds: [44001, 44002, 44003], dt_s: 5e-6, t_max_s: 0.05, solver: "RK4StHybridCustom", npools: 200, bootstrap_replicates: 20000, bootstrap_seed: 92001 }, remote: { host: profile.host, project_directory: profile.project_directory, commit: "a".repeat(40), branch: "main", dirty: false }, effects: { start_simulation: true, submit_later_stages: false, modify_campaign_files: false, record_submission_receipt: true, submit_final_validation: true }, local_sync: { status: "synchronized", receipt_sha256: receipt } } } }));
  await page.route("**/api/v1/zeus/submissions/mot-3d-final-validation/confirm", (route) => {
    confirmed = true;
    return route.fulfill({ status: 201, json: { api_version: 1, data: { status: "submitted", campaign_id: id, stage: "final_validation", chain: submitted, submitted_at: "2026-10-12T10:01:00Z", local_sync: { status: "synchronized", receipt_sha256: receipt } } } });
  });
  await page.goto("/");
  await page.getByRole("link", { name: "Zeus connection" }).click();
  await page.getByLabel("Technion username").fill("tal.noa");
  await page.getByRole("button", { name: "Connect and check status" }).click();
  await page.getByRole("button", { name: "Inspect campaign" }).click();
  const stage = page.getByRole("region", { name: "Run sealed Final Validation" });
  await stage.getByRole("button", { name: "Check Final Validation status" }).click();
  await stage.getByRole("button", { name: "Review Final Validation jobs" }).click();
  await expect(stage.getByRole("heading", { name: "Submit Final Validation" })).toBeFocused();
  await expect(stage.getByText("20", { exact: true })).toBeVisible();
  await expect(stage.getByText("5 µs", { exact: true })).toBeVisible();
  await stage.getByRole("button", { name: "Submit Final Validation to Zeus" }).click();
  await expect(stage.getByText("Final Validation is running on Zeus")).toBeVisible();
  await stage.getByRole("button", { name: "Refresh status" }).click();
  await expect(stage.getByText("Scheduler work finished")).toBeVisible();
  await expect(stage.getByText(/not yet scientifically validated, synchronized, or reported/)).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth > document.documentElement.clientWidth)).toBe(false);
  expect((await new AxeBuilder({ page }).analyze()).violations).toEqual([]);
});
